#!/usr/bin/env python3
"""Temporary regression probes for the existing documentation entrypoint."""
import pathlib, shutil, subprocess, tempfile, unittest
SOURCE=pathlib.Path('/Users/sunchongsheng/code/spec-flow.worktrees/issue-165')
class Contracts(unittest.TestCase):
 def setUp(self):
  self.temp=tempfile.TemporaryDirectory(prefix='spec-flow-165-static-');self.root=pathlib.Path(self.temp.name)
  for n in ['SKILL.md','README.md','README.zh-CN.md','references','scripts']:
   s=SOURCE/n
   if s.is_dir():shutil.copytree(s,self.root/n)
   else:shutil.copy2(s,self.root/n)
 def tearDown(self):self.temp.cleanup()
 def run_check(self):
  p=subprocess.run(['bash','scripts/check-docs.sh'],cwd=self.root,text=True,capture_output=True)
  return p.returncode,p.stdout
 def replace(self,path,old,new):
  p=self.root/path;t=p.read_text();assert old in t;p.write_text(t.replace(old,new))
 def test_current_documentation_passes(self):self.assertEqual(self.run_check()[0],0)
 def test_missing_flow_owner_is_rejected(self):
  self.replace('references/one-path.md','## 三、阶段事实与衔接','## 三、背景')
  self.assertNotEqual(self.run_check()[0],0,'没有阶段正文的 owner 应报红')
 def test_duplicate_state_definition_is_rejected(self):
  p=self.root/'references/phase-handoff.md'
  with p.open('a') as f:f.write('\n## 状态模型\n\n| 状态 | 当前阶段事实 | 后续衔接 |\n|---|---|---|\n| `SPEC_READY` | 另一定义 | 继续 |\n')
  self.assertNotEqual(self.run_check()[0],0,'交接文件重建状态正文应报红')
 def test_missing_expected_delivery_contract_is_rejected(self):
  self.replace('references/phase-handoff.md','预期交付','期望产出未登记')
  self.assertNotEqual(self.run_check()[0],0,'应保留预期交付信息组')
 def test_missing_git_shape_section_is_rejected(self):
  self.replace('references/release-discipline.md','## 一、Git 分支形态','## 一、背景')
  self.assertNotEqual(self.run_check()[0],0,'release 应有 Git 形态映射正文')
 def test_alternative_guide_expression_is_allowed(self):
  p=self.root/'references/spec-maturity.md'
  p.write_text('# 规格表达方法\n\n用段落说明输入、输出、异常和验收，不固定列数或例数。流程见 [one-path](one-path.md)，准入见 [gate-details](gate-details.md)。\n')
  self.assertEqual(self.run_check()[0],0,'可替换指南不得被固定写法锁死')
 def test_prose_delivery_fields_are_allowed(self):
  p=self.root/'references/phase-handoff.md';t=p.read_text();a=t.index('| 信息组 |');b=t.index('\nspec 保留目标',a)
  t=t[:a]+'获批依据和预期交付：原规格版本与成果、必要测试、配套文档。\n全部实际来源及必要依赖：全部方案和实现提交，已就绪的依赖及理由。\n就绪证据和候选结果：通过结果与逐类核验，既有内容不重复。\n'+t[b:];p.write_text(t)
  self.assertEqual(self.run_check()[0],0,'交付字段的语义可用段落表达')
 def test_handoff_open_guard_is_common_to_entry_types(self):
  t=(self.root/'references/gate-details.md').read_text();block=t.split('### 委托识别',1)[1].split('- **定向入口',1)[0]
  self.assertTrue('open' in block and '已关闭' in block,'交接issue的open/已关闭守卫须在共同授权条件中，不能只属定向入口')
 def test_existing_reference_path_guard_still_works(self):
  (self.root/'references/code-map.md').unlink();self.assertNotEqual(self.run_check()[0],0)
if __name__=='__main__':unittest.main(verbosity=2)

