#!/usr/bin/env python3
"""Git-only fake repo exercise, not a release engine or production test."""
import json, pathlib, subprocess, tempfile, unittest
class Promotion(unittest.TestCase):
 def setUp(self):
  self.temp=tempfile.TemporaryDirectory(prefix='spec-flow-165-git-');self.r=pathlib.Path(self.temp.name)
  self.commands=[];self.git('init','-b','master');self.git('config','user.name','Workflow Fixture');self.git('config','user.email','fixture@example.invalid');self.git('config','commit.gpgsign','false');self.git('config','tag.gpgsign','false')
  self.put('shared.md','base agreement\n');self.base=self.commit('fixture baseline');self.git('branch','staging');self.git('checkout','-b','dev')
  self.put('docs/specs/task.md','Approved #12: export, normal/boundary/failure tests and docs/guide.md.\n');self.plan=self.commit('plan PR #101')
  self.put('app.py','def export(rows):\n    return list(rows)\n');self.put('test_app.py','import unittest\nfrom app import export\nclass ExportTest(unittest.TestCase):\n def test_normal(self): self.assertEqual(export([1]), [1])\n def test_empty(self): self.assertEqual(export([]), [])\n def test_failure(self):\n  with self.assertRaises(TypeError): export(None)\n');self.impl=self.commit('implementation PR #102')
  self.put('docs/guide.md','Export guide for task #12.\n');self.put('shared.md','base agreement\n#12 export contract\n');self.docs=self.commit('supplementary PR #103')
  (self.r/'docs/archive').mkdir(parents=True);self.git('mv','docs/specs/task.md','docs/archive/task.md');self.archive=self.commit('archive PR #104')
  self.put('shared.md','base agreement\n#12 export contract\n#99 unready change\n');self.other=self.commit('unready task #99')
  self.record={'issue':12,'expected':{'spec':'docs/specs/task.md','code':['app.py','test_app.py'],'docs':['docs/guide.md']},'approved_spec':self.plan,'plan_pr':{'number':101,'commit':self.plan},'implementation_prs':[{'number':102,'commit':self.impl},{'number':103,'commit':self.docs},{'number':104,'commit':self.archive}],'actual_spec':'docs/archive/task.md','dependencies':{'state':'none','reason':'no other task required'},'tests':{'result':'PASS','command':'python3 -m unittest -v'},'deployment_required':False}
 def tearDown(self):self.temp.cleanup()
 def git(self,*args):
  p=subprocess.run(['git',*args],cwd=self.r,text=True,capture_output=True)
  self.commands.append({'command':['git',*args],'exit':p.returncode,'stdout':p.stdout.strip(),'stderr':p.stderr.strip()})
  if p.returncode:raise AssertionError(p.stderr)
  return p.stdout.strip()
 def put(self,n,text):p=self.r/n;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text)
 def commit(self,msg):self.git('add','.');self.git('commit','-m',msg);return self.git('rev-parse','HEAD')
 def pick(self,*commits):
  self.git('checkout','staging')
  for c in commits:self.git('cherry-pick',c)
 def test_split_plan_and_all_implementation_sources_are_complete(self):
  self.pick(self.plan,self.impl,self.docs,self.archive)
  self.assertEqual((self.r/'docs/archive/task.md').read_text(),self.git('show',self.plan+':docs/specs/task.md')+'\n')
  self.assertTrue((self.r/'docs/guide.md').exists());self.assertFalse((self.r/'docs/specs/task.md').exists())
  p=subprocess.run(['python3','-m','unittest','-v'],cwd=self.r,text=True,capture_output=True);self.assertEqual(p.returncode,0,p.stderr)
 def test_expected_document_missing_is_detectable_before_delivery(self):
  self.pick(self.plan,self.impl);self.assertFalse((self.r/'docs/guide.md').exists());self.assertIn('docs/guide.md',self.record['expected']['docs'])
 def test_existing_approved_content_is_verified_without_repick(self):
  self.pick(self.plan);before=self.git('rev-parse','HEAD');expected=self.git('show',self.plan+':docs/specs/task.md')
  self.assertEqual((self.r/'docs/specs/task.md').read_text(),expected+'\n');self.assertEqual(before,self.git('rev-parse','HEAD'))
 def test_archival_includes_body_not_only_old_path_deletion(self):
  self.pick(self.plan,self.impl,self.docs,self.archive);self.assertTrue((self.r/'docs/archive/task.md').is_file());self.assertIn('Approved #12',(self.r/'docs/archive/task.md').read_text())
 def test_later_deletion_is_detectable_from_current_candidate(self):
  self.pick(self.plan,self.impl,self.docs,self.archive);self.git('rm','docs/guide.md');self.commit('later deletion')
  self.assertFalse((self.r/'docs/guide.md').exists());self.assertIn('docs/guide.md',self.record['expected']['docs'])
 def test_shared_file_does_not_take_unready_dev_head(self):
  self.pick(self.plan,self.impl,self.docs,self.archive);current=(self.r/'shared.md').read_text();self.assertIn('#12',current);self.assertNotIn('#99',current);self.assertIn('#99',self.git('show','dev:shared.md'))
 def test_source_record_keeps_plan_and_every_supplementary_commit(self):
  self.assertEqual(len(self.record['implementation_prs']),3)
  for x in [self.record['plan_pr'],*self.record['implementation_prs']]:self.assertEqual(len(x['commit']),40);self.git('cat-file','-e',x['commit'])
 def test_fake_tag_snapshot_keeps_same_tree_and_ancestry(self):
  self.pick(self.plan,self.impl,self.docs,self.archive);candidate=self.git('rev-parse','HEAD');self.git('tag','-a','v26.11.0','-m','fixture only')
  old=self.git('rev-parse','master');self.assertEqual(old,self.git('rev-parse','master')) # no success action yet
  tree=self.git('rev-parse','v26.11.0^{tree}');new=self.git('commit-tree',tree,'-p',old,'-p',candidate,'-m','fixture success snapshot')
  self.assertEqual(tree,self.git('rev-parse',new+'^{tree}'));self.assertIn(candidate,self.git('rev-list','--parents','-n','1',new))
  # No branch push/update or actual deployment; even the fake master remains old.
  self.assertEqual(old,self.git('rev-parse','master'))
if __name__=='__main__':unittest.main(verbosity=2)
